<template>
  <section class="shotBatchPanel" aria-label="镜头批次">
    <header class="batchTools"><label>制作单元<select v-model="sequenceId" aria-label="批次制作单元" :disabled="editing || busy"><option v-for="sequence in sequences" :key="sequence.sequenceId" :value="sequence.sequenceId">{{ sequence.name }}</option></select></label><el-button :disabled="busy || !shots.length" @click="newBatch">准备新批次</el-button><el-button :disabled="busy" @click="load">刷新批次</el-button></header>
    <p class="batchHint">独立任务按渠道上限排队。依赖项等待所选上游结果保存为固定候选后执行，不自动采用结果。费用未核实时显示未知。</p>
    <p v-if="error" class="batchError" role="alert">{{ error }}</p>
    <form v-if="editing" class="batchForm" @submit.prevent="prepare">
      <label>批次名称<input v-model="name" required maxlength="200" /></label>
      <p class="batchHint">当前 {{ entries.length }} 项。已有参考只能选择工作空间内固定版本；上游结果可指定为下游参考。准备范围后再确认执行。</p>
      <ol class="entryList">
        <li v-for="(entry, index) in entries" :key="entry.itemId">
          <details :open="index === 0"><summary>{{ index + 1 }} · {{ shotTitle(entry.shotId) }} · {{ mediaLabels[entry.mediaType] }} · {{ entry.request.modelId || '未选择模型' }}<span v-if="entryIssue(entry)" class="batchError"> · 需调整</span></summary>
            <div class="entryFields">
              <label>镜头<select v-model="entry.shotId" aria-label="镜头"><option v-for="shot in shots" :key="shot.shotId" :value="shot.shotId">{{ shot.title }}</option></select></label>
              <label>媒体类型<select v-model="entry.mediaType" aria-label="媒体类型" @change="resetModel(entry)"><option value="image">图片</option><option value="video">视频</option><option value="audio">音频</option></select></label>
              <label class="wideField">生成模型<select :value="modelKey(entry)" aria-label="生成模型" @change="chooseModel(entry, ($event.target as HTMLSelectElement).value)"><option value="">选择模型</option><option v-for="model in models.filter(model => model.type === entry.mediaType)" :key="JSON.stringify([model.providerId, model.modelId])" :value="JSON.stringify([model.providerId, model.modelId])">{{ model.providerLabel }} / {{ model.label }}</option></select></label>
              <label class="wideField">{{ entry.mediaType === 'audio' ? '朗读文本' : '生成提示词' }}<textarea v-model="entry.request.prompt" rows="3" maxlength="100000" required /></label>
              <template v-if="modelFor(entry)">
                <label v-if="entry.mediaType === 'image'">数量<input v-model.number="entry.request.n" type="number" min="1" :max="modelFor(entry)?.maxImageCount || 1" :disabled="!modelFor(entry)?.maxImageCount" required /></label>
                <label v-if="entry.mediaType === 'image' && modelFor(entry)?.imageSizes?.length">尺寸<select v-model="entry.request.size" aria-label="尺寸"><option value="">渠道默认</option><option v-for="size in modelFor(entry)!.imageSizes" :key="size" :value="size">{{ size }}</option></select></label>
                <label v-if="ratios(entry)?.length">画幅<select v-model="entry.request.ratio" aria-label="画幅"><option value="">渠道默认</option><option v-for="ratio in ratios(entry)" :key="ratio" :value="ratio">{{ ratio }}</option></select></label>
                <label v-if="entry.mediaType === 'image' && modelFor(entry)?.imageQualities?.length">质量<select v-model="entry.request.quality" aria-label="质量"><option value="">渠道默认</option><option v-for="quality in modelFor(entry)!.imageQualities" :key="quality" :value="quality">{{ quality }}</option></select></label>
                <template v-if="entry.mediaType === 'video'">
                  <label v-if="modeOptions(entry).length">生成模式<select v-model="entry.mode" aria-label="生成模式"><option v-for="mode in modeOptions(entry)" :key="JSON.stringify(mode)" :value="JSON.stringify(mode)">{{ modeLabel(mode) }}</option></select></label>
                  <label v-if="durations(entry).length">时长（秒）<select v-model="entry.request.duration" aria-label="时长（秒）"><option :value="undefined">渠道默认</option><option v-for="duration in durations(entry)" :key="duration" :value="duration">{{ duration }}</option></select></label>
                  <label v-if="resolutions(entry).length">分辨率<select v-model="entry.request.resolution" aria-label="分辨率"><option value="">渠道默认</option><option v-for="resolution in resolutions(entry)" :key="resolution" :value="resolution">{{ resolution }}</option></select></label>
                  <label v-if="modelFor(entry)?.audio === 'optional'">音轨<select v-model="entry.request.generateAudio" aria-label="音轨"><option :value="undefined">渠道默认</option><option :value="true">生成音轨</option><option :value="false">不生成音轨</option></select></label>
                </template>
                <template v-if="entry.mediaType === 'audio'">
                  <label v-if="modelFor(entry)?.voices?.length">音色<select v-model="entry.request.voice" aria-label="音色"><option value="">请选择音色</option><option v-for="voice in modelFor(entry)!.voices" :key="voice.voice" :value="voice.voice">{{ voice.title }}</option></select></label>
                  <label v-if="modelFor(entry)?.audioFormats?.length">格式<select v-model="entry.request.format" aria-label="格式"><option value="">渠道默认</option><option v-for="format in modelFor(entry)!.audioFormats" :key="format" :value="format">{{ format.toUpperCase() }}</option></select></label>
                  <label v-if="modelFor(entry)?.audioSpeedRange">语速<input v-model.number="entry.request.speed" type="number" :min="modelFor(entry)!.audioSpeedRange!.min" :max="modelFor(entry)!.audioSpeedRange!.max" step="0.05" placeholder="渠道默认" /></label>
                </template>
              </template>
            </div>
            <fieldset v-if="referenceOptions(entry).length"><legend>镜头固定参考</legend><label v-for="file in referenceOptions(entry)" :key="file.path" class="referenceChoice"><input v-model="entry.files" type="checkbox" :value="file.path" />{{ file.label }}</label></fieldset>
            <fieldset><legend>上游结果依赖</legend><div v-for="(dependency, number) in entry.dependencies" :key="number" class="dependencyFields"><label>上游任务<select v-model="dependency.itemId" aria-label="上游任务"><option value="">选择上游</option><option v-for="(parent, position) in entries.filter(parent => parent.itemId !== entry.itemId)" :key="parent.itemId" :value="parent.itemId">{{ shotTitle(parent.shotId) }} · {{ mediaLabels[parent.mediaType] }} · {{ entries.findIndex(item => item.itemId === parent.itemId) + 1 }}</option></select></label><label>用作<select v-model="dependency.slot" aria-label="用作"><option v-for="(label, slot) in slotLabels" :key="slot" :value="slot">{{ label }}</option></select></label><label>结果序号<input v-model.number="dependency.resultNumber" type="number" min="1" max="10" required /></label><el-button text :aria-label="`移除依赖 ${number + 1}`" @click="entry.dependencies.splice(number, 1)">移除</el-button></div><el-button size="small" :disabled="entries.length < 2" @click="entry.dependencies.push({ itemId: '', slot: 'images', resultNumber: 1 })">添加上游依赖</el-button></fieldset>
            <p v-if="entryIssue(entry)" class="batchError" role="alert">{{ entryIssue(entry) }}</p><el-button size="small" text :disabled="entries.length === 1" @click="entries.splice(index, 1)">移除此任务</el-button>
          </details>
        </li>
      </ol>
      <div class="formActions"><el-button :disabled="entries.length >= 200" @click="addEntry()">添加任务</el-button><el-button :disabled="busy" @click="editing = false">收起草稿</el-button><el-button type="primary" nativeType="submit" :loading="busy" :disabled="!!formIssue">查看并确认范围</el-button></div><p v-if="formIssue" class="batchError" role="alert">{{ formIssue }}</p>
    </form>
    <section v-if="selected" class="batchDetail" aria-label="批次执行范围">
      <header><h3>{{ selected.name }}</h3><span>{{ stateLabels[selected.state] }} · {{ selected.items.length }} 项 · {{ batchCostLabel(selected) }}</span></header>
      <p v-if="selected.error" class="batchError" role="alert">{{ selected.error }}</p>
      <p class="batchHint">确认后按下方固定范围执行。暂停编排后，已排队和已提交任务仍会继续，可能计费；未提交的排队任务可在任务中心取消。失败任务不会自动新建付费请求。</p>
      <ol class="scopeList"><li v-for="(item, index) in selected.items" :key="item.itemId"><header><strong>{{ index + 1 }} · {{ item.title }} · {{ mediaLabels[item.mediaType] }}</strong><span :class="{ batchError: ['failed','blocked','unknown','interrupted'].includes(item.status) }">{{ taskLabels[item.status] || item.status }}</span></header><p>{{ providerName(item.request.providerId) }} / {{ item.request.modelId }} · {{ parameters(item.resolvedRequest || item.request, item.mediaType) }}</p><p class="scopePrompt">{{ item.request.prompt }}</p><p class="batchHint">{{ quoteLabel(item.quote) }}</p><p v-for="file in requestFiles(item.request)" :key="file.path" class="batchHint">固定参考：{{ fileLabel(file.path) }}</p><p v-for="(dependency, number) in item.dependencies" :key="number" class="batchHint">依赖 {{ selected.items.find(parent => parent.itemId === dependency.itemId)?.title }} · 结果 {{ dependency.resultIndex + 1 }} → {{ slotLabels[dependency.slot] }}</p><p v-if="item.reason || item.task?.error || item.task?.collectionError" class="batchError">{{ item.reason || item.task?.error || item.task?.collectionError }}</p><el-button v-if="item.task" size="small" @click="center.open({directory: store.directory, id:item.task.id})">查看任务与结果（{{ item.task.resultCount }}）</el-button></li></ol>
      <div class="formActions"><el-button v-if="selected.state === 'running'" :loading="busy" @click="control('pause')">暂停后续编排</el-button><el-button v-else-if="selected.state !== 'archived' && (selected.state !== 'finished' || selected.items.some(item => item.status === 'ready' || item.task?.canResume || item.task?.collectionError))" type="primary" :loading="busy" @click="control('run')">{{ selected.state === 'ready' ? `确认并执行 ${selected.items.length} 项` : '确认继续原批次' }}</el-button><el-button v-if="selected.state !== 'running'" :disabled="busy" @click="selectedId = ''">收起范围</el-button></div>
    </section>
    <section class="batchHistory"><h3>批次记录</h3><p v-if="!batches.length" class="batchHint">尚无批次。准备新批次可冻结范围，确认前不会生成。</p><ol><li v-for="batch in batches" :key="batch.batchId"><button @click="selectedId = batch.batchId; editing = false">{{ batch.name }}</button><span>{{ stateLabels[batch.state] }} · {{ summary(batch) }}</span><time>{{ new Date(batch.createdAt).toLocaleString() }}</time></li></ol></section>
  </section>
</template>

<script setup lang="ts">
import { computed, onScopeDispose, reactive, ref, watch } from "vue";
import axios from "axios";
import { getMediaCapabilityError, type MediaModel, type MediaGenerationRequest } from "@toonflow/tools-scaffold/runtime";
import type { BatchInput, BatchView } from "@toonflow/server/production/batches";
import type { MediaCostQuote } from "@toonflow/providers/mediaCosts";
import { useProductionStore, productionError } from "@/stores/production";
import { useTaskCenterStore } from "@/stores/taskCenter";
const props = defineProps<{ active: boolean }>(); const store = useProductionStore(); const center = useTaskCenterStore();
const headers = { "x-toonflow-workspace": "1" }; const models = ref<MediaModel[]>([]); const batches = ref<BatchView[]>([]); const sequenceId = ref(""); const selectedId = ref("");
const sequences = computed(() => store.project?.sequences.filter(sequence => !sequence.archived) ?? []); const sequence = computed(() => sequences.value.find(sequence => sequence.sequenceId === sequenceId.value));
const shots = computed(() => sequence.value?.shotIds.flatMap(id => store.project?.shots.find(shot => shot.shotId === id) ?? []) ?? []); const selected = computed(() => batches.value.find(batch => batch.batchId === selectedId.value));
const editing = ref(false); const name = ref(""); const busy = ref(false); const error = ref(""); let draftDirectory = ""; let draftBatchId = ""; let draftPrepared = false; let timer: ReturnType<typeof setTimeout> | undefined; let reader: AbortController | undefined;
type Entry = { itemId: string; shotId: string; mediaType: "image" | "video" | "audio"; request: MediaGenerationRequest; mode: string; files: string[]; dependencies: { itemId: string; slot: "images" | "videos" | "audios" | "firstFrame" | "lastFrame"; resultNumber: number }[] };
const entries = reactive<Entry[]>([]); const mediaLabels = { image: "图片", video: "视频", audio: "音频" }; const slotLabels = { images: "参考图片", videos: "参考视频", audios: "参考音频", firstFrame: "首帧", lastFrame: "尾帧" };
const stateLabels = { ready: "待确认", running: "编排中", paused: "已暂停，需核对", finished: "本次编排结束", interrupted: "服务重启，待继续", archived: "迁移历史，只读" };
const taskLabels: Record<string, string> = { ready: "待提交", waiting: "等待依赖", blocked: "依赖失败，未提交", queued: "渠道排队中", submitting: "提交中", running: "生成中", downloading: "保存中", completed: "已完成", partial: "部分完成", failed: "失败", unknown: "待核对", interrupted: "待恢复", cancelled: "已取消排队" };
function shotTitle(id: string) { return store.project?.shots.find(shot => shot.shotId === id)?.title || "镜头缺失"; }
function modelFor(entry: Entry) { return models.value.find(model => model.providerId === entry.request.providerId && model.modelId === entry.request.modelId && model.type === entry.mediaType); }
function modelKey(entry: Entry) { return entry.request.providerId ? JSON.stringify([entry.request.providerId, entry.request.modelId]) : ""; }
function chooseModel(entry: Entry, key: string) { const [providerId = "", modelId = ""] = key ? JSON.parse(key) : []; entry.request = { providerId, modelId, prompt: entry.request.prompt, size: "", ratio: "", quality: "", resolution: "", voice: "", format: "", ...(entry.mediaType === "image" ? { n: 1 } : {}) }; const mode = modeOptions(entry).find(mode => mode === "text") ?? modeOptions(entry)[0]; entry.mode = mode ? JSON.stringify(mode) : ""; }
function resetModel(entry: Entry) { const model = models.value.find(model => model.type === entry.mediaType); chooseModel(entry, model ? JSON.stringify([model.providerId, model.modelId]) : ""); }
function addEntry(shotId = shots.value[0]?.shotId) { if (!shotId) return; const entry: Entry = { itemId: crypto.randomUUID(), shotId, mediaType: "image", request: { providerId: "", modelId: "", prompt: store.project?.shots.find(shot => shot.shotId === shotId)?.story || shotTitle(shotId) }, mode: "", files: [], dependencies: [] }; resetModel(entry); entries.push(entry); }
function saveDraft() { if (draftDirectory && entries.length && !draftPrepared) store.batchDrafts.set(draftDirectory, JSON.stringify({ entries, name: name.value, sequenceId: sequenceId.value, batchId: draftBatchId })); }
function newBatch() { if (draftDirectory !== store.directory || draftPrepared || !entries.length) { draftDirectory = store.directory; const saved = store.batchDrafts.get(draftDirectory); entries.splice(0); if (saved) { const draft = JSON.parse(saved); entries.push(...draft.entries); name.value = draft.name; sequenceId.value = draft.sequenceId; draftBatchId = draft.batchId; } else { shots.value.forEach(shot => addEntry(shot.shotId)); name.value = `${sequence.value?.name || '镜头'}生成批次`; draftBatchId = crypto.randomUUID(); } draftPrepared = false; } editing.value = true; selectedId.value = ""; error.value = ""; }
function ratios(entry: Entry) { return entry.mediaType === "image" ? modelFor(entry)?.imageRatios : entry.mediaType === "video" ? modelFor(entry)?.videoRatios : []; }
function durations(entry: Entry) { return [...new Set(modelFor(entry)?.durationResolutionMap?.flatMap(item => item.duration) ?? [])]; }
function resolutions(entry: Entry) { return [...new Set(modelFor(entry)?.durationResolutionMap?.filter(item => entry.request.duration === undefined || item.duration.includes(entry.request.duration)).flatMap(item => item.resolution) ?? [])]; }
function modeOptions(entry: Entry) { const modes = modelFor(entry)?.mode; return Array.isArray(modes) ? modes.filter((mode): mode is NonNullable<MediaGenerationRequest["mode"]> => typeof mode === 'string' ? ['text','singleImage','startEndRequired','endFrameOptional','startFrameOptional'].includes(mode) : Array.isArray(mode) && mode.every(item => typeof item === 'string' && /^(image|video|audio)Reference:\d+$/.test(item))) : []; }
function modeLabel(mode: NonNullable<MediaGenerationRequest["mode"]>) { const labels: Record<string,string> = { text: "文字生成", singleImage: "单图参考", startEndRequired: "首尾帧", endFrameOptional: "首帧，尾帧可选", startFrameOptional: "尾帧，首帧可选" }; return Array.isArray(mode) ? mode.map(item => item.replace('imageReference:', '图片参考上限 ').replace('videoReference:', '视频参考上限 ').replace('audioReference:', '音频参考上限 ')).join(' / ') : labels[mode] || mode; }
function referenceOptions(entry: Entry) { const shot = store.project?.shots.find(shot => shot.shotId === entry.shotId); return shot?.references.flatMap(reference => { const version = store.project?.assetVersions.find(version => version.versionId === reference.versionId); const asset = store.project?.assets.find(asset => asset.assetId === reference.assetId); return version?.files.filter(file => /^(image|video|audio)\//.test(file.mimeType)).map((file, index) => ({ ...file, label: `${asset?.name || '素材'} · ${file.view || index + 1} · ${file.mimeType.split('/')[0]}` })) ?? []; }) ?? []; }
function requestFor(entry: Entry, preview = false): MediaGenerationRequest {
  const request: MediaGenerationRequest = Object.fromEntries(Object.entries(entry.request).filter(([, value]) => value !== "" && value !== undefined)) as unknown as MediaGenerationRequest;
  if (entry.mediaType === "video" && entry.mode) request.mode = JSON.parse(entry.mode);
  for (const path of entry.files) { const file = referenceOptions(entry).find(file => file.path === path); if (!file) continue; const field = file.mimeType.startsWith('image/') ? 'images' : file.mimeType.startsWith('video/') ? 'videos' : 'audios'; request[field] = [...request[field] ?? [], { path: file.path, mimeType: file.mimeType }]; }
  if (entry.mediaType === "video" && ['startEndRequired','endFrameOptional','startFrameOptional'].includes(String(request.mode))) { const images = request.images ?? []; delete request.images; if (request.mode === 'startFrameOptional') { request.lastFrame = images[0]; request.firstFrame = images[1]; } else { request.firstFrame = images[0]; request.lastFrame = images[1]; } if (images.length > 2) request.images = images.slice(2); }
  if (preview) for (const dependency of entry.dependencies) { const file = { path: 'pendingDependency', mimeType: `${dependency.slot === 'videos' ? 'video' : dependency.slot === 'audios' ? 'audio' : 'image'}/pending` }; if (dependency.slot === 'firstFrame' || dependency.slot === 'lastFrame') request[dependency.slot] = file; else request[dependency.slot] = [...request[dependency.slot] ?? [], file]; }
  return request;
}
function entryIssue(entry: Entry) { const model = modelFor(entry); if (!model) return '请选择当前媒体类型的可用模型'; if (!entry.request.prompt.trim()) return '请输入提示词或朗读文本'; if (entry.dependencies.some(dependency => !dependency.itemId || !entries.some(parent => parent.itemId === dependency.itemId) || dependency.itemId === entry.itemId)) return '请选择有效的上游任务'; if (entry.files.some(path => !referenceOptions(entry).some(file => file.path === path))) return '镜头参考已改变，请重新选择固定参考'; return getMediaCapabilityError(model, entry.mediaType, requestFor(entry, true)) || ''; }
const formIssue = computed(() => !entries.length ? '至少保留一个任务' : entries.map(entry => entryIssue(entry) ? `${shotTitle(entry.shotId)}：${entryIssue(entry)}` : '').find(Boolean) || '');
function requestFiles(request: MediaGenerationRequest) { return [...request.images ?? [], ...request.videos ?? [], ...request.audios ?? [], ...request.firstFrame ? [request.firstFrame] : [], ...request.lastFrame ? [request.lastFrame] : []]; }
function fileLabel(path: string) { const version = store.project?.assetVersions.find(version => version.files.some(file => file.path === path)); const asset = store.project?.assets.find(asset => asset.assetId === version?.assetId); return version ? [asset?.name, version.description, version.files.find(file => file.path === path)?.view, path].filter(Boolean).join(' · ') : path; }
function providerName(id: string) { return models.value.find(model => model.providerId === id)?.providerLabel || id; }
function parameters(request: MediaGenerationRequest, type: string) { return [type === 'image' ? `${request.n ?? 1} 张` : type === 'video' ? request.duration ? `${request.duration} 秒` : '时长由渠道决定' : request.voice ? `音色 ${request.voice}` : '音色由渠道决定', request.size, request.ratio, request.resolution, request.quality, request.format, request.mode ? modeLabel(request.mode) : '', request.generateAudio === undefined ? '' : request.generateAudio ? '生成音轨' : '不生成音轨', request.imageTransport?.streamImages ? '流式图片' : '', request.imageTransport?.codexCli ? '兼容模式' : '', request.speed === undefined ? '' : `${request.speed} 倍速`].filter(Boolean).join(' · '); }
function summary(batch: BatchView) { return Object.entries(batch.counts).map(([status, count]) => `${taskLabels[status] || status} ${count}`).join(' / '); }
async function load() { clearTimeout(timer); reader?.abort(); if (!props.active || !store.directory) return; const directory = store.directory; const current = reader = new AbortController(); try { const [list, available] = await Promise.all([axios.get<{data: BatchView[]}>("/api/production/batches/list", {params:{directory},headers,signal:current.signal}),axios.get<{data:MediaModel[]}>("/api/ai/media/models",{signal:current.signal})]); if (current.signal.aborted || directory !== store.directory) return; batches.value = list.data.data; models.value = available.data.data; error.value = ''; } catch (cause) { if (!current.signal.aborted && directory === store.directory) error.value = productionError(cause); } finally { if (!current.signal.aborted && props.active && directory === store.directory) timer = setTimeout(load, 3000); } }
async function prepare() { const directory = draftDirectory; busy.value = true; error.value = ''; try { store.requireDirectory(directory); if (!sequenceId.value || !store.project) throw Error('制作单元已改变，请重新准备'); const input: BatchInput = {batchId:draftBatchId,name:name.value,sequenceId:sequenceId.value,expectedRevision:store.project.revision,items:entries.map(entry=>({itemId:entry.itemId,shotId:entry.shotId,mediaType:entry.mediaType,request:requestFor(entry) as BatchInput['items'][number]['request'],dependencies:entry.dependencies.map(dependency=>({itemId:dependency.itemId,slot:dependency.slot,resultIndex:dependency.resultNumber-1}))}))}; const {data} = await axios.post<{data:BatchView}>("/api/production/batches/prepare",{directory,...input},{headers}); if (directory !== store.directory) return; batches.value.unshift(data.data); selectedId.value = data.data.batchId; editing.value = false; draftPrepared = true; store.batchDrafts.delete(directory); } catch (cause) { if (directory === store.directory) error.value = productionError(cause); } finally { busy.value = false; } }
async function control(action:'run'|'pause') { const directory=store.directory, batch=selected.value; if (!batch) return; busy.value=true; error.value=''; try { const {data}=await axios.post<{data:BatchView}>("/api/production/batches/control",{directory,batchId:batch.batchId,fingerprint:batch.fingerprint,action},{headers}); if (directory===store.directory) {const index=batches.value.findIndex(row=>row.batchId===batch.batchId); if(index>=0)batches.value[index]=data.data; void load();} } catch(cause){if(directory===store.directory)error.value=productionError(cause);}finally{busy.value=false;} }
watch(sequences, value=>{if(!value.some(sequence=>sequence.sequenceId===sequenceId.value))sequenceId.value=value[0]?.sequenceId||'';},{immediate:true});
watch([()=>props.active,()=>store.directory],()=>{if(draftDirectory&&draftDirectory!==store.directory){saveDraft();editing.value=false;entries.splice(0);selectedId.value='';batches.value=[];}void load();},{immediate:true});
onScopeDispose(()=>{saveDraft();reader?.abort();clearTimeout(timer);});
function batchCostLabel(batch: BatchView) { const summary = batch.costSummary; return summary ? [...summary.currencies.map(row => `${row.currency} ${row.exposure}（含预估）`), ...(summary.unknownCount ? [`${summary.unknownCount} 项费用未知`] : [])].join(" · ") || "尚无费用依据" : "费用未知"; }
function quoteLabel(quote?: MediaCostQuote) { return quote?.kind === "estimated" ? `固定预估 ${quote.money.currency} ${quote.money.amount} · 单价来源：${quote.rate.source} · ${new Date(quote.rate.updatedAt).toLocaleString()}` : `费用未知：${quote?.reason ?? "旧批次没有保存单价依据"}`; }
</script>

